// Independent rule-by-rule check of the real engine (src/engine.js + src/data.js).
// One numbered rule = one assertion; the numbers are those of ../RULES-CHECKLIST.md (which this file generates: node logic-test.js --md).
// Run: node logic-test.js   -> one line per failing rule ("rule N: expected X, got Y"), exit code 1 on any failure.
// Rule: src: 'R' = stated in the printed rulebook (high confidence), 'U' = our ruling / not verified against the box.
const fs = require('fs'), path = require('path');
const T = require('./tlib.js'); const { FA, D } = T;
const RULES = [];
const R = (sec, src, text, fn) => RULES.push({ n: RULES.length + 1, sec, src, text, fn });
class Miss extends Error { constructor(e, g) { super('x'); this.e = e; this.g = g; } }
const eq = (exp, got) => { if (JSON.stringify(exp) !== JSON.stringify(got)) throw new Miss(exp, got); };
const J = x => JSON.stringify(x);
// ---- state builders (state is set by hand, everything after is done by real moves) ----
let TK = 0;
// g1 on a custom track: sp = [[planes, trafficIcons, tabs|null], ...]
const mkTrack = sp => { const k = 'lt' + (++TK); D.tracks[k] = { size: sp.length, sp }; return k; };
function mk(o) {
  o = o || {}; const G = T.round(o.sc || 'g1', o.seed || 5, o.pv, o.cv, o.opt);
  if (o.sp) { G.tk = mkTrack(o.sp); G.planes = o.sp.map(s => s[0]); G.mods.tabs = o.sp.some(s => s[2]); G.mods.traffic = o.sp.some(s => s[1] > 0); }
  else if (!o.keep) G.planes.fill(0);
  if (o.pos) G.pl.pos = o.pos; return G;
}
// a round with the given four numbers: pilot axis, pilot engine, co-pilot axis, co-pilot engine (planes cleared unless o.keep)
function fly(pa, pe, ca, ce, o) { const G = mk(Object.assign({ pv: [pa, pe], cv: [ca, ce] }, o || {})); T.axisEng(G, pa, pe, ca, ce); return G; }
// start of the last round: plane on the airport, planes cleared, switches as given
function fin(o) {
  o = o || {}; const G = T.game(o.sc || 'g1', 9, o.opt); const tr = D.tracks[G.tk];
  T.toRound(G, 6); G.planes.fill(0); G.pl.pos = o.pos || tr.size; G.pl.axis = o.axis || 0;
  const sw = (a, n, v) => { for (let i = 0; i < n; i++) a[i] = v === undefined ? 1 : v; };
  if (o.gear !== 0) { sw(G.pl.sw.lg, 3); G.pl.aeroB = 7; } if (o.flaps !== 0) { sw(G.pl.sw.fl, 4); G.pl.aeroO = 12; }
  if (o.br) for (let i = 0; i < o.br; i++) G.pl.sw.br[i] = 1;
  if (o.ice !== undefined) G.pl.ice = o.ice;
  T.roll(G); return G;
}
const landDice = (G, pa, pe, ca, ce) => { T.dice(G, 0, [pa, pe]); T.dice(G, 1, [ca, ce]); G.turn = G.first; T.axisEng(G, pa, pe, ca, ce); };
const lostWhy = G => G.result && !G.result.win ? G.result.why : (G.result ? 'WIN' : 'open');

// =============== A. SETUP AND ROUND STRUCTURE ===============
R('Setup', 'R', 'The game lasts 7 rounds; the altitude track runs 6000, 5000, 4000, 3000, 2000, 1000, 0 ft, one row per round.', () => { eq([7, [6000, 5000, 4000, 3000, 2000, 1000, 0]], [D.rounds, D.alt.gy.map(r => r[0])]); });
R('Setup', 'R', 'At setup the plane stands on approach space 1, the axis is level, the aerodynamics markers are blue 4 / orange 8, the brake marker is not yet at 2, no coffee is held.', () => { const G = T.game('g1', 1); eq([1, 0, 4, 8, 0], [G.pl.pos, G.pl.axis, G.pl.aeroB, G.pl.aeroO, G.coffee]); eq(0, [0, 1, 2].filter(i => G.pl.sw.br[i]).length); });
R('Setup', 'R', 'Exactly two players: Pilot (left seat, blue) and Co-pilot (right seat, orange), each with 4 dice.', () => { const G = T.game('g1', 1); eq([4, 4], [G.dice[0].length, G.dice[1].length]); eq([false, false], [FA.validMoves(G, 2).length > 0, FA.validMoves(G, -1).length > 0]); });
R('Setup', 'R', 'Briefing comes first: nobody can place a die before both crew are ready; dice are rolled only when both are ready, each die showing 1 to 6.', () => { const G = T.game('g1', 2); eq(0, FA.validMoves(G, 0).filter(m => m.t === 'place').length); T.mv(G, 0, { t: 'ready' }); eq('brief', G.phase); T.mv(G, 1, { t: 'ready' }); eq('place', G.phase); eq(true, [0, 1].every(s => G.dice[s].every(d => d.v >= 1 && d.v <= 6 && !d.u))); });
R('Setup', 'R', 'The first player of round 1 is the Pilot; first player alternates every round (round 2 Co-pilot, round 3 Pilot, ...).', () => { const G = T.game('g1', 3); const f = [G.first]; for (let r = 1; r < 7; r++) { T.toRound(G, r); f.push(G.first); } eq([0, 1, 0, 1, 0, 1, 0], f); });
R('Setup', 'U', 'Reroll tokens: the green/yellow altitude side gives one at 6000 ft and one at 2000 ft; the red/black side gives one at 6000 ft only. One token is in hand at the start of round 1.', () => { const g = T.game('g1', 1); eq(1, g.rrHand); const h = []; const G = T.game('g1', 1); for (let r = 1; r < 7; r++) { const b = G.rrHand; T.toRound(G, r); h.push(G.rrHand - b); } eq([0, 0, 0, 1, 0, 0], h); const B = T.game('r1', 1); eq(1, B.rrHand); const k = []; for (let r = 1; r < 7; r++) { const b = B.rrHand; T.toRound(B, r); k.push(B.rrHand - b); } eq([0, 0, 0, 0, 0, 0], k); });
R('Setup', 'R', 'Components: 3 coffee tokens, 3 reroll tokens, 12 plane tokens, a traffic die with faces 2, 3, 3, 4, 4, 5.', () => { eq([3, 3, 12, [2, 3, 3, 4, 4, 5]], [D.coffeeMax, D.rerollTotal, D.planeSupply, D.speedFaces.slice().sort((a, b) => a - b)]); });
R('Setup', 'R', 'Players alternate placing one die per turn, starting with the round\'s first player.', () => { const G = mk({ pv: [3, 3, 3, 3], cv: [3, 3, 3, 3] }); const t = [G.turn]; T.put(G, 0, 3, 'co0'); t.push(G.turn); T.put(G, 1, 3, 'co1'); t.push(G.turn); T.put(G, 0, 3, 'ra0'); t.push(G.turn); eq([0, 1, 0, 1], t); });
R('Setup', 'R', 'A player who has no dice left does not skip the other: the other keeps placing alone.', () => { const G = mk({ pv: [3], cv: [3, 3, 3] }); T.put(G, 0, 3, 'co0'); const a = G.turn; T.put(G, 1, 3, 'co1'); const b = G.turn; eq([1, 1], [a, b]); });
R('Setup', 'R', 'Each die goes on a free space of its owner\'s colour: Pilot-only, Co-pilot-only and shared spaces are respected.', () => { const G = mk({ pv: [3, 3, 3, 3], cv: [3, 3, 3, 3] }); eq([false, false, true, true, false], [T.can(G, 0, 3, 'ax1'), T.can(G, 1, 3, 'ax0'), T.can(G, 0, 3, 'ax0'), T.can(G, 1, 3, 'co0'), T.can(G, 1, 3, 'en0')]); });
R('Setup', 'R', 'A space holds only one die: an occupied space cannot be used again in the same round.', () => { const G = mk({ pv: [3, 3, 3, 3], cv: [3, 3, 3, 3] }); T.put(G, 0, 3, 'co0'); G.turn = 1; eq(false, T.can(G, 1, 3, 'co0')); });
R('Setup', 'R', 'A die that has no legal space at all may be set aside as the turn; otherwise it may not.', () => { const G = mk({ pv: [3, 3, 3, 3], cv: [3, 3, 3, 3] }); eq(0, FA.validMoves(G, 0).filter(m => m.t === 'toss').length); for (const k of ['ax0', 'en0', 'ra0', 'co0', 'co1', 'co2', 'lg1']) G.slots[k] = { s: 0, v: 3, k: 'd' }; G.turn = 0; eq(true, FA.validMoves(G, 0).some(m => m.t === 'toss')); });
R('Setup', 'R', 'At the end of a round all dice come back, spaces are emptied, the altitude drops one row and the next round starts in the briefing.', () => { const G = fly(3, 1, 3, 1); eq([1, 'brief', 0], [G.round, G.phase, Object.keys(G.slots).length]); eq(true, G.dice[0].every(d => d.u)); });
R('Setup', 'R', 'During placement, spoken numbers are banned: the app only lets crew send preset phrases before the roll, at most 3 each, and none contain dice values.', () => { const G = T.game('g1', 2); for (const c of ['adv2', 'plane', 'level']) T.mv(G, 0, { t: 'say', c }); eq(0, FA.validMoves(G, 0).filter(m => m.t === 'say').length); T.roll(G); eq(0, FA.validMoves(G, 0).filter(m => m.t === 'say').length); });

// =============== B. AXIS ===============
R('Axis', 'R', 'Axis: each player must put one die on their own axis space (any value 1-6).', () => { const G = mk({ pv: [1, 2, 3, 4], cv: [5, 6, 1, 2] }); const r = [1, 2, 3, 4, 5, 6].every(v => { const g = mk({ pv: [v], cv: [v] }); return T.can(g, 0, v, 'ax0') && T.can(g, 1, v, 'ax1'); }); eq(true, r); });
R('Axis', 'R', 'The axis moves only when BOTH axis dice are down: after the first axis die the axis has not moved.', () => { const G = mk({ pv: [4, 1, 1, 1], cv: [1, 1, 1, 1] }); T.put(G, 0, 4, 'ax0'); eq(0, G.pl.axis); });
R('Axis', 'R', 'Axis tilts by the DIFFERENCE of the two axis dice, toward the player with the higher die (Pilot higher and Co-pilot higher tilt opposite ways).', () => { const a = fly(4, 1, 3, 1), b = fly(3, 1, 4, 1); eq(true, a.pl.axis !== 0 && a.pl.axis === -b.pl.axis && Math.abs(a.pl.axis) === 1); const c = fly(6, 1, 4, 1); eq(2, Math.abs(c.pl.axis)); });
R('Axis', 'R', 'Equal axis dice leave the axis where it is.', () => { const G = fly(5, 1, 5, 1); eq(0, G.pl.axis); const H = mk({ pv: [4, 1, 3, 1], cv: [3, 1, 1, 1] }); });
R('Axis', 'R', 'Axis tilt is cumulative from round to round and never resets by itself.', () => { const G = mk({ pv: [3, 1], cv: [4, 1] }); T.axisEng(G, 3, 1, 4, 1); const a1 = G.pl.axis; T.roll(G); T.dice(G, 0, [3, 1]); T.dice(G, 1, [4, 1]); G.turn = G.first; T.axisEng(G, 3, 1, 4, 1); eq([1, 2], [Math.abs(a1), Math.abs(G.pl.axis)]); });
R('Axis', 'R', 'The axis can be brought back: tilt 1 toward one side then 1 toward the other is level again.', () => { const G = mk({ pv: [3, 1], cv: [4, 1] }); T.axisEng(G, 3, 1, 4, 1); T.roll(G); T.dice(G, 0, [4, 1]); T.dice(G, 1, [3, 1]); G.turn = G.first; T.axisEng(G, 4, 1, 3, 1); eq(0, G.pl.axis); });
R('Axis', 'R', 'A tilt of 2 either way is survivable.', () => { const G = fly(3, 1, 5, 1); eq(['open', 2], [lostWhy(G), Math.abs(G.pl.axis)]); const H = fly(5, 1, 3, 1); eq('open', lostWhy(H)); });
R('Axis', 'R', 'A tilt of 3 (reaching the red marks) toward the Co-pilot side is an immediate loss: spin.', () => { const G = fly(1, 1, 4, 1); eq('spin', lostWhy(G)); });
R('Axis', 'R', 'A tilt of 3 toward the Pilot side is an immediate loss: spin. A total of 3 reached over two rounds (1 then 2) also spins.', () => { const G = fly(4, 1, 1, 1); eq('spin', lostWhy(G)); const H = fly(3, 1, 4, 1); T.roll(H); T.dice(H, 0, [3, 1]); T.dice(H, 1, [5, 1]); H.turn = H.first; T.axisEng(H, 3, 1, 5, 1); eq('spin', lostWhy(H)); });
R('Axis', 'R', 'A spin ends the game at once: no later move is legal.', () => { const G = fly(1, 1, 4, 1); eq([0, 0], [FA.validMoves(G, 0).length, FA.validMoves(G, 1).length]); });
R('Axis', 'R', 'A missing axis die at the end of a round is a loss (Co-pilot axis not placed).', () => { const G = mk({ pv: [3, 2, 2, 2], cv: [4, 4, 4, 4] }); T.put(G, 0, 3, 'ax0'); T.put(G, 1, 4, 'en1'); T.put(G, 0, 2, 'en0'); T.put(G, 1, 4, 'ra1'); T.put(G, 0, 2, 'ra0'); T.put(G, 1, 4, 'ra2'); T.put(G, 0, 2, 'co0'); T.put(G, 1, 4, 'co1'); eq('mandatory', lostWhy(G)); });
R('Axis', 'R', 'A missing engine die at the end of a round is a loss (Pilot engine not placed).', () => { const G = mk({ pv: [3, 2, 2, 2], cv: [3, 4, 4, 4] }); T.put(G, 0, 3, 'ax0'); T.put(G, 1, 3, 'ax1'); T.put(G, 0, 2, 'co0'); T.put(G, 1, 4, 'en1'); T.put(G, 0, 2, 'co1'); T.put(G, 1, 4, 'ra1'); T.put(G, 0, 2, 'co2'); T.put(G, 1, 4, 'ra2'); eq('mandatory', lostWhy(G)); });

// =============== C. ENGINES AND THE APPROACH TRACK ===============
R('Engines', 'R', 'Engines: each player must put one die on their own engine space (any value).', () => { const r = [1, 2, 3, 4, 5, 6].every(v => { const g = mk({ pv: [v], cv: [v] }); return T.can(g, 0, v, 'en0') && T.can(g, 1, v, 'en1'); }); eq(true, r); });
R('Engines', 'R', 'Speed is the SUM of the two engine dice; the plane does not move until both engine dice are down.', () => { const G = mk({ pv: [3, 6, 3, 1], cv: [3, 6, 1, 1] }); T.put(G, 0, 3, 'ax0'); T.put(G, 1, 3, 'ax1'); T.put(G, 0, 6, 'en0'); eq(1, G.pl.pos); T.put(G, 1, 6, 'en1'); eq(3, G.pl.pos); });
R('Engines', 'R', 'Speed up to the blue marker (4): the plane stays (sums 2, 3, 4 advance 0).', () => { const p = [[1, 1], [1, 2], [2, 2]].map(([a, b]) => fly(3, a, 3, b).pl.pos); eq([1, 1, 1], p); });
R('Engines', 'R', 'Speed above blue and up to orange (5 to 8): the plane advances 1 space.', () => { const p = [[2, 3], [3, 4], [4, 4], [3, 3]].map(([a, b]) => fly(3, a, 3, b).pl.pos); eq([2, 2, 2, 2], p); });
R('Engines', 'R', 'Speed above orange (9 and more, up to 12): the plane advances 2 spaces.', () => { const p = [[4, 5], [5, 5], [6, 6], [3, 6]].map(([a, b]) => fly(3, a, 3, b).pl.pos); eq([3, 3, 3, 3], p); });
R('Engines', 'R', 'Each landing gear that turns green moves the blue marker up by one (4 -> 5 -> 6 -> 7); sum 5 then advances 0 after the first gear.', () => { const G = mk({ pv: [1, 2, 5, 3], cv: [1, 1, 1, 1] }); T.put(G, 0, 1, 'lg0'); eq(5, G.pl.aeroB); T.put(G, 0, 3, 'lg1'); eq(6, G.pl.aeroB); T.put(G, 0, 5, 'lg2'); eq(7, G.pl.aeroB); });
R('Engines', 'R', 'With blue at 5 (one gear down), a speed of 5 advances 0 spaces; with blue at 4 it advances 1.', () => { const G = mk({ pv: [3, 2], cv: [3, 3] }); G.pl.aeroB = 5; G.pl.sw.lg[0] = 1; T.axisEng(G, 3, 2, 3, 3); eq(1, G.pl.pos); });
R('Engines', 'R', 'Each flap that turns green moves the orange marker up by one (8 -> 9 ... -> 12).', () => { const G = mk({ pv: [1, 1, 1, 1], cv: [1, 2, 4, 5] }); const a = []; T.put(G, 1, 1, 'fl0'); a.push(G.pl.aeroO); T.put(G, 1, 2, 'fl1'); a.push(G.pl.aeroO); T.put(G, 1, 4, 'fl2'); a.push(G.pl.aeroO); T.put(G, 1, 5, 'fl3'); a.push(G.pl.aeroO); eq([9, 10, 11, 12], a); });
R('Engines', 'R', 'With orange at 9 (one flap out), a speed of 9 advances only 1 space, not 2.', () => { const G = mk({ pv: [3, 4], cv: [3, 5] }); G.pl.aeroO = 9; G.pl.sw.fl[0] = 1; T.axisEng(G, 3, 4, 3, 5); eq(2, G.pl.pos); });
R('Engines', 'R', 'With all gear and all flaps (blue 7, orange 12) a speed of 7 advances 0, 8 advances 1, 12 advances 1, never 2.', () => { const a = [[3, 4], [4, 4], [6, 6]].map(([x, y]) => { const G = mk({ pv: [3, x], cv: [3, y] }); G.pl.aeroB = 7; G.pl.aeroO = 12; G.pl.sw.lg = [1, 1, 1]; G.pl.sw.fl = [1, 1, 1, 1]; T.axisEng(G, 3, x, 3, y); return G.pl.pos; }); eq([1, 2, 2], a); });
R('Engines', 'R', 'Advancing is checked one space at a time: with a plane token on the space you are leaving, you collide and lose.', () => { const G = fly(3, 3, 3, 3, { keep: 0, sp: [[1, 0, null], [0, 0, null], [0, 0, null], [0, 0, null], [0, 0, null]] }); eq('collision', lostWhy(G)); });
R('Engines', 'R', 'Planes on spaces you only fly over do not hurt: starting on a free space, moving 2 over a plane on space 3 is fine.', () => { const G = fly(5, 5, 5, 5, { sp: [[0, 0, null], [0, 0, null], [1, 0, null], [0, 0, null], [0, 0, null], [0, 0, null]] }); eq(['open', 3], [lostWhy(G), G.pl.pos]); });
R('Engines', 'R', 'A plane on the space you step INTO (adjacent) is not hit this round; you are only in danger when you try to leave that space later.', () => { const G = fly(3, 3, 3, 3, { sp: [[0, 0, null], [1, 0, null], [0, 0, null], [0, 0, null], [0, 0, null]] }); eq(['open', 2], [lostWhy(G), G.pl.pos]); });
R('Engines', 'R', 'A move of 2 also checks the second space you leave: a plane on space 2 is hit when advancing from 1 by 2 (leaving space 2).', () => { const G = fly(5, 5, 5, 5, { sp: [[0, 0, null], [1, 0, null], [0, 0, null], [0, 0, null], [0, 0, null]] }); eq('collision', lostWhy(G)); });
R('Engines', 'R', 'Advancing 0 spaces is never checked: a plane on your own space is harmless if you do not move.', () => { const G = fly(3, 1, 3, 1, { sp: [[1, 0, null], [0, 0, null], [0, 0, null], [0, 0, null], [0, 0, null]] }); eq(['open', 1], [lostWhy(G), G.pl.pos]); });
R('Engines', 'R', 'Overshooting the airport (advancing beyond the last space) is a loss.', () => { const G = mk({ pv: [3, 3], cv: [3, 3], pos: 7 }); T.axisEng(G, 3, 3, 3, 3); eq('overshoot', lostWhy(G)); });
R('Engines', 'R', 'Holding pattern: standing on the airport space before the last round, every engine result must advance 0 (sum 2 is safe, sum 5 overshoots).', () => { const a = mk({ pv: [3, 1], cv: [3, 1], pos: 7 }); T.axisEng(a, 3, 1, 3, 1); eq(['open', 7], [lostWhy(a), a.pl.pos]); });
R('Engines', 'R', 'Arriving on the airport space exactly is fine (no loss when you reach it).', () => { const G = fly(3, 3, 3, 3, { pos: 6 }); eq(['open', 7], [lostWhy(G), G.pl.pos]); });
R('Engines', 'R', 'Reaching the last altitude row (0 ft) while not on the airport space is a loss: the plane crashes short of the runway.', () => { const G = T.game('g1', 9); T.toRound(G, 5); G.planes.fill(0); G.pl.pos = 3; T.roll(G); T.dice(G, 0, [3, 1]); T.dice(G, 1, [3, 1]); G.turn = G.first; T.axisEng(G, 3, 1, 3, 1); eq('short', lostWhy(G)); });
R('Engines', 'R', 'Reaching the last row ON the airport space is fine (round 7 starts).', () => { const G = T.game('g1', 9); T.toRound(G, 5); G.planes.fill(0); G.pl.pos = 7; T.roll(G); T.dice(G, 0, [3, 1]); T.dice(G, 1, [3, 1]); G.turn = G.first; T.axisEng(G, 3, 1, 3, 1); eq([6, 'open'], [G.round, lostWhy(G)]); });

// =============== D. TRACK TABS (corridor) ===============
R('Corridor', 'R', 'Tight corridor: when leaving a space that has tab marks, the axis must be in one of the marked positions, else loss.', () => { const sp = [[0, 0, [0]], [0, 0, null], [0, 0, null], [0, 0, null], [0, 0, null]]; const G = fly(3, 3, 4, 3, { sp }); eq('corridor', lostWhy(G)); });
R('Corridor', 'R', 'With the axis inside the marked positions the plane leaves a tab space freely.', () => { const sp = [[0, 0, [0, 1]], [0, 0, null], [0, 0, null], [0, 0, null], [0, 0, null]]; const G = fly(3, 3, 4, 3, { sp }); eq(['open', 2], [lostWhy(G), G.pl.pos]); });
R('Corridor', 'R', 'The axis is checked as it stands AFTER this round\'s axis dice resolved, and only if the plane actually leaves (advance 0 is not checked).', () => { const sp = [[0, 0, [0]], [0, 0, null], [0, 0, null], [0, 0, null], [0, 0, null]]; const G = fly(3, 1, 4, 1, { sp }); eq(['open', 1], [lostWhy(G), G.pl.pos]); });
R('Corridor', 'R', 'Tab check comes before the collision check on the space being left.', () => { const sp = [[1, 0, [0]], [0, 0, null], [0, 0, null], [0, 0, null], [0, 0, null]]; const G = fly(3, 3, 4, 3, { sp }); eq('corridor', lostWhy(G)); });
R('Corridor', 'R', 'Only the space being left matters: a tab on a space that is merely flown over (second step) is checked when leaving it.', () => { const sp = [[0, 0, null], [0, 0, [0]], [0, 0, null], [0, 0, null], [0, 0, null]]; const G = fly(3, 5, 4, 5, { sp }); eq('corridor', lostWhy(G)); });

// =============== E. RADIO ===============
R('Radio', 'R', 'Pilot has ONE radio space; Co-pilot has TWO radio spaces; radio takes any value, and only its owner\'s colour.', () => { const G = mk({ pv: [3, 3, 3, 3], cv: [3, 3, 3, 3] }); eq([true, false, true, true, false], [T.can(G, 0, 3, 'ra0'), T.can(G, 0, 3, 'ra1'), T.can(G, 1, 3, 'ra1'), T.can(G, 1, 3, 'ra2'), T.can(G, 1, 3, 'ra0')]); });
R('Radio', 'R', 'Radio die of value 1 clears a plane on the space the plane is standing on.', () => { const G = mk({ pv: [1], cv: [1], sp: [[1, 0, null], [0, 0, null], [0, 0, null], [0, 0, null], [0, 0, null]] }); T.put(G, 0, 1, 'ra0'); eq(0, G.planes[0]); });
R('Radio', 'R', 'Radio die of value v removes a plane token on the space v-1 ahead of the plane (count from the plane\'s own space as 1).', () => { const sp = [[0, 0, null], [0, 0, null], [1, 0, null], [1, 0, null], [0, 0, null], [0, 0, null]]; const G = mk({ pv: [3], cv: [1], sp }); T.put(G, 0, 3, 'ra0'); eq([0, 0, 0, 1, 0, 0], G.planes); });
R('Radio', 'R', 'Radio value 3 with the plane on space 2 targets space 4.', () => { const G = mk({ pv: [3], cv: [1], sp: [[0, 0, null], [0, 0, null], [0, 0, null], [1, 0, null], [0, 0, null], [0, 0, null]] }); G.pl.pos = 2; T.put(G, 0, 3, 'ra0'); eq(0, G.planes[3]); });
R('Radio', 'R', 'Radio removes only ONE token even if the space holds several.', () => { const G = mk({ pv: [1], cv: [1], sp: [[3, 0, null], [0, 0, null], [0, 0, null], [0, 0, null], [0, 0, null]] }); T.put(G, 0, 1, 'ra0'); eq(2, G.planes[0]); });
R('Radio', 'R', 'Radio aimed at an empty space (or beyond the airport) changes nothing and is not an error.', () => { const G = mk({ pv: [6], cv: [1], sp: [[0, 0, null], [1, 0, null], [0, 0, null], [0, 0, null], [0, 0, null]] }); T.put(G, 0, 6, 'ra0'); eq([0, 1, 0, 0, 0], G.planes); });
R('Radio', 'R', 'The removed plane token goes back to the supply (a later traffic roll can use it again).', () => { const sp = [[2, 0, null], [0, 0, null], [0, 0, null], [0, 0, null], [0, 0, null]]; const G = mk({ pv: [1], cv: [1], sp }); const before = FA.planesOnTrack ? 0 : 0; T.put(G, 0, 1, 'ra0'); eq(1, G.planes.reduce((a, b) => a + b, 0)); });
R('Radio', 'R', 'Radio resolves immediately, so clearing a plane before the engines are placed makes the later advance safe.', () => { const sp = [[1, 0, null], [0, 0, null], [0, 0, null], [0, 0, null], [0, 0, null]]; const G = mk({ pv: [1, 3, 3], cv: [3, 3], sp }); T.put(G, 0, 1, 'ra0'); T.axisEng(G, 3, 3, 3, 3); eq(['open', 2], [lostWhy(G), G.pl.pos]); });
R('Radio', 'R', 'Radio works from the plane\'s current space, so after the plane has moved the target shifts with it.', () => { const sp = [[0, 0, null], [0, 0, null], [0, 0, null], [0, 0, null], [1, 0, null], [0, 0, null]]; const G = mk({ pv: [3], cv: [1], sp, pos: 3 }); T.put(G, 0, 3, 'ra0'); const H = mk({ pv: [2], cv: [1], sp, pos: 4 }); T.put(H, 0, 2, 'ra0'); const K = mk({ pv: [3], cv: [1], sp, pos: 1 }); T.put(K, 0, 3, 'ra0'); eq([0, 0, 1], [G.planes[4], H.planes[4], K.planes[4]]); });

// =============== F. LANDING GEAR / FLAPS / BRAKES ===============
R('Gear', 'R', 'Landing gear (Pilot): three spaces needing 1-2, 3-4 and 5-6; a die outside the pair is refused.', () => { const G = mk({ pv: [1, 2, 3, 4], cv: [1, 1, 1, 1] }); const ok = [[1, 'lg0'], [2, 'lg0'], [3, 'lg1'], [4, 'lg1']].every(([v, k]) => T.can(G, 0, v, k)); const no = [[3, 'lg0'], [1, 'lg1'], [2, 'lg2'], [4, 'lg0']].some(([v, k]) => T.can(G, 0, v, k)); eq([true, false], [ok, no]); const H = mk({ pv: [5, 6], cv: [1] }); eq([true, true], [T.can(H, 0, 5, 'lg2'), T.can(H, 0, 6, 'lg2')]); });
R('Gear', 'R', 'Landing gear spaces can be filled in any order (5-6 first is allowed).', () => { const G = mk({ pv: [5, 3], cv: [1] }); eq(true, T.can(G, 0, 5, 'lg2') && T.can(G, 0, 3, 'lg1')); });
R('Gear', 'R', 'Only the Pilot can use landing gear; the Co-pilot cannot.', () => { const G = mk({ pv: [1], cv: [1, 3, 5] }); eq(false, T.can(G, 1, 1, 'lg0') || T.can(G, 1, 3, 'lg1') || T.can(G, 1, 5, 'lg2')); });
R('Gear', 'R', 'Putting a die on a gear space turns its light green (switch set) at once.', () => { const G = mk({ pv: [1], cv: [1] }); T.put(G, 0, 1, 'lg0'); eq([1, 0, 0], G.pl.sw.lg); });
R('Flaps', 'R', 'Flaps (Co-pilot): four spaces needing 1-2, 2-3, 4-5, 5-6.', () => { const G = mk({ pv: [1], cv: [1, 2] }); eq([true, true], [T.can(G, 1, 1, 'fl0'), T.can(G, 1, 2, 'fl0')]); eq([false, false, false], [T.can(G, 1, 3, 'fl0'), T.can(G, 1, 1, 'fl1'), T.can(G, 1, 2, 'fl3')]); const H = mk({ pv: [1], cv: [4, 5, 6] }); H.pl.sw.fl = [1, 1, 0, 0]; eq([true, true, false], [T.can(H, 1, 4, 'fl2'), T.can(H, 1, 5, 'fl2'), T.can(H, 1, 6, 'fl2')]); H.pl.sw.fl = [1, 1, 1, 0]; eq([true, true, false], [T.can(H, 1, 5, 'fl3'), T.can(H, 1, 6, 'fl3'), T.can(H, 1, 4, 'fl3')]); });
R('Flaps', 'R', 'Flaps must be set strictly in order: flap 2 needs flap 1 green, flap 3 needs flap 2, flap 4 needs flap 3.', () => { const G = mk({ pv: [1], cv: [2, 2, 4, 5] }); eq([false, false, false], [T.can(G, 1, 2, 'fl1'), T.can(G, 1, 4, 'fl2'), T.can(G, 1, 5, 'fl3')]); T.put(G, 1, 2, 'fl0'); eq(true, T.can(G, 1, 2, 'fl1')); });
R('Flaps', 'R', 'Only the Co-pilot can use flaps; the Pilot cannot.', () => { const G = mk({ pv: [1, 2], cv: [1] }); eq(false, T.can(G, 0, 1, 'fl0') || T.can(G, 0, 2, 'fl0')); });
R('Brakes', 'R', 'Brakes (Pilot): three spaces needing exactly 2, then 4, then 6.', () => { const G = mk({ pv: [2, 4, 6, 3], cv: [1] }); eq([true, false, false, false], [T.can(G, 0, 2, 'br0'), T.can(G, 0, 3, 'br0'), T.can(G, 0, 4, 'br0'), T.can(G, 0, 6, 'br0')]); });
R('Brakes', 'R', 'Brakes must be set in order: 4 only after 2, 6 only after 4.', () => { const G = mk({ pv: [2, 4, 6], cv: [1] }); eq([false, false], [T.can(G, 0, 4, 'br1'), T.can(G, 0, 6, 'br2')]); T.put(G, 0, 2, 'br0'); eq([true, false], [T.can(G, 0, 4, 'br1'), T.can(G, 0, 6, 'br2')]); T.put(G, 0, 4, 'br1'); eq(true, T.can(G, 0, 6, 'br2')); });
R('Brakes', 'R', 'Only the Pilot can use the brakes.', () => { const G = mk({ pv: [1], cv: [2, 4, 6] }); eq(false, T.can(G, 1, 2, 'br0')); });
R('Brakes', 'R', 'The brake marker stands at 0 (none) until the first brake, then 2, 4, 6 after each brake.', () => { const G = mk({ pv: [2, 4, 6], cv: [1] }); const a = [FA.brakeVal ? 0 : 0]; const v = () => (G.pl.sw.br[2] ? 6 : G.pl.sw.br[1] ? 4 : G.pl.sw.br[0] ? 2 : 0); const o = [v()]; T.put(G, 0, 2, 'br0'); o.push(v()); T.put(G, 0, 4, 'br1'); o.push(v()); T.put(G, 0, 6, 'br2'); o.push(v()); eq([0, 2, 4, 6], o); });
R('Brakes', 'R', 'Gear, flaps and brakes are optional in a round: a round may end without any of them.', () => { const G = fly(3, 1, 3, 1); eq(['open', 1], [lostWhy(G), G.round]); });
R('Brakes', 'R', 'Placing a die on an already-green group is only possible on another empty space: gear/flaps/brakes are not toggled twice (a green switch stays green across rounds).', () => { const G = mk({ pv: [1, 1], cv: [1, 1] }); T.put(G, 0, 1, 'lg0'); T.dice(G, 0, [1, 1, 1, 1]); G.slots = {}; G.turn = 0; T.put(G, 0, 1, 'lg0'); eq([1, 0, 0], G.pl.sw.lg); eq(5, G.pl.aeroB); });

// =============== G. CONCENTRATION AND COFFEE ===============
R('Coffee', 'R', 'Concentration: three shared spaces, any value, either player.', () => { const G = mk({ pv: [1, 2, 3], cv: [4, 5, 6] }); eq(true, [[0, 1], [0, 2], [0, 3], [1, 4], [1, 5], [1, 6]].every(([s, v]) => T.can(G, s, v, 'co0'))); });
R('Coffee', 'R', 'A die on a concentration space gives one coffee token.', () => { const G = mk({ pv: [3], cv: [3] }); T.put(G, 0, 3, 'co0'); eq(1, G.coffee); });
R('Coffee', 'R', 'You can never hold more than 3 coffee tokens; the 4th die on concentration is just spent.', () => { const G = mk({ pv: [3, 3, 3, 3], cv: [3, 3, 3, 3] }); G.coffee = 3; T.put(G, 0, 3, 'co0'); eq(3, G.coffee); });
R('Coffee', 'R', 'Spending a coffee token changes the die being placed by +1 or -1; the token is used up.', () => { const G = mk({ pv: [3, 3], cv: [3, 3] }); G.coffee = 2; T.put(G, 0, 3, 'br0', -1); eq([1, [1, 0, 0]], [G.coffee, G.pl.sw.br]); });
R('Coffee', 'R', 'One coffee can raise a 1 to a 2 so that it fits the first brake / gear / flap values.', () => { const G = mk({ pv: [1, 1], cv: [1] }); G.coffee = 1; eq(true, T.can(G, 0, 1, 'br0', 1)); T.put(G, 0, 1, 'br0', 1); eq([0, [1, 0, 0]], [G.coffee, G.pl.sw.br]); });
R('Coffee', 'R', 'Several coffee tokens may be spent on one die (each +1 or -1): a 2 becomes 4 with two tokens.', () => { const G = mk({ pv: [2, 1], cv: [1] }); G.coffee = 2; G.pl.sw.br[0] = 1; eq(true, T.can(G, 0, 2, 'br1', 2)); T.put(G, 0, 2, 'br1', 2); eq(0, G.coffee); });
R('Coffee', 'R', 'Coffee can go down as well as up: a 5 becomes a 4 with -1.', () => { const G = mk({ pv: [5], cv: [1] }); G.coffee = 1; G.pl.sw.br[0] = 1; eq(true, T.can(G, 0, 5, 'br1', -1)); });
R('Coffee', 'R', 'A die can never leave the range 1-6: a 6 cannot become 7 and a 1 cannot become 0 (no wrapping).', () => { const G = mk({ pv: [6, 1], cv: [1] }); G.coffee = 3; const m = FA.validMoves(G, 0).filter(x => x.t === 'place'); eq(false, m.some(x => x.d === G.dice[0].findIndex(d => !d.u && d.v === 6) && x.c > 0)); eq(false, m.some(x => x.d === G.dice[0].findIndex(d => !d.u && d.v === 1) && x.c < 0)); });
R('Coffee', 'R', 'You cannot spend more coffee than you hold.', () => { const G = mk({ pv: [3], cv: [3] }); G.coffee = 1; const m = FA.validMoves(G, 0).filter(x => x.t === 'place'); eq(0, m.filter(x => Math.abs(x.c) > 1).length); });
R('Coffee', 'R', 'Unspent coffee tokens stay for later rounds.', () => { const G = mk({ pv: [3, 1], cv: [3, 1] }); G.coffee = 2; T.axisEng(G, 3, 1, 3, 1); eq(2, G.coffee); });
R('Coffee', 'R', 'Either player may spend any coffee token: the Co-pilot can use a token the Pilot earned.', () => { const G = mk({ pv: [3], cv: [3, 3] }); T.put(G, 0, 3, 'co0'); eq(true, T.can(G, 1, 3, 'fl0', -1)); });
R('Coffee', 'R', 'The coffee change counts for the effect: a die changed by coffee acts with its final value (axis tilt uses the changed number).', () => { const G = mk({ pv: [3, 1], cv: [3, 1] }); G.coffee = 1; T.put(G, 0, 3, 'ax0', 1); T.put(G, 1, 3, 'ax1'); eq(1, Math.abs(G.pl.axis)); });

// =============== H. REROLL TOKENS ===============
R('Reroll', 'R', 'A reroll token can be used any time during the placement phase while unplaced dice remain; it is spent.', () => { const G = mk({ pv: [3, 3], cv: [3, 3] }); G.rrHand = 1; eq(true, FA.validMoves(G, 0).some(m => m.t === 'rr')); T.mv(G, 0, { t: 'rr' }); eq(0, G.rrHand); });
R('Reroll', 'R', 'Without a reroll token no reroll is offered.', () => { const G = mk({ pv: [3], cv: [3] }); G.rrHand = 0; eq(false, FA.validMoves(G, 0).some(m => m.t === 'rr')); });
R('Reroll', 'R', 'No reroll in the briefing (the dice are not yet rolled).', () => { const G = T.game('g1', 2); G.rrHand = 1; eq(false, FA.validMoves(G, 0).some(m => m.t === 'rr')); });
R('Reroll', 'U', 'Either player may reroll any of their own UNPLACED dice (including none); already placed dice never change.', () => { const G = mk({ pv: [3, 3], cv: [3, 3] }); G.rrHand = 1; T.put(G, 0, 3, 'co0'); const p = G.dice[0].findIndex(d => !d.u && d.v === 3); T.mv(G, 1, { t: 'rr' }); T.mv(G, 0, { t: 'rrpick', m: [true, true, true, true] }); T.mv(G, 1, { t: 'rrpick', m: [false, false, false, false] }); eq([3, 3], [G.slots.co0.v, G.dice[1][0].v]); });
R('Reroll', 'R', 'The reroll can be used by a player off their own turn, and after they have placed all their dice (while the other still holds one).', () => { const G = mk({ pv: [3], cv: [3, 3] }); G.rrHand = 1; T.put(G, 0, 3, 'co0'); eq(true, FA.validMoves(G, 0).some(m => m.t === 'rr')); eq(true, FA.validMoves(G, 1).some(m => m.t === 'rr')); });
R('Reroll', 'R', 'Rerolled dice get fresh values 1-6; dice the player did not select keep their value.', () => { const G = mk({ pv: [3, 3, 3, 3], cv: [3, 3, 3, 3] }); G.rrHand = 1; G.rrScript = null; T.mv(G, 0, { t: 'rr' }); T.mv(G, 0, { t: 'rrpick', m: [true, false, false, false] }); T.mv(G, 1, { t: 'rrpick', m: [false, true, false, false] }); eq([true, [3, 3, 3], [3, 3, 3]], [G.dice[0][0].v >= 1 && G.dice[0][0].v <= 6 && G.dice[1][1].v >= 1 && G.dice[1][1].v <= 6, G.dice[0].slice(1).map(d => d.v), [G.dice[1][0].v, G.dice[1][2].v, G.dice[1][3].v]]); });
R('Reroll', 'R', 'A reroll token that was on the altitude track goes into your supply when that row is reached (not before).', () => { const G = T.game('g1', 1); const a = G.rrHand; T.toRound(G, 3); const b = G.rrHand; T.toRound(G, 4); eq([1, 1, 2], [a, b, G.rrHand]); });
R('Reroll', 'R', 'Only 3 reroll tokens exist in total: the Twin Thrust bonus can only pay out while one is left unused in the box.', () => { const G = T.game('g1', 1, { abil: [] }); G.abil = ['mastery']; G.rrHand = 3; T.roll(G); T.dice(G, 0, [3, 3]); T.dice(G, 1, [3, 3]); G.turn = G.first; T.axisEng(G, 3, 3, 3, 3); eq(3, G.rrHand); });

// =============== I. TRAFFIC DIE ===============
R('Traffic', 'R', 'Traffic die: at the start of a round, roll it once per icon on the space the plane stands on; the plane token is placed v-1 spaces ahead (die 2 = next space ... 5 = four spaces ahead).', () => { const sp = [[0, 2, null], [0, 0, null], [0, 0, null], [0, 0, null], [0, 0, null], [0, 0, null], [0, 0, null]]; const G = mk({ sp }); G.planes.fill(0); FA._.startRound(G); const n = G.planes.reduce((a, b) => a + b, 0); eq(true, n === 2 && G.planes.every((c, i) => c === 0 || (i >= 1 && i <= 4))); });
R('Traffic', 'R', 'No icons on the plane\'s space: no roll at the start of the round.', () => { const sp = [[0, 0, null], [0, 3, null], [0, 0, null], [0, 0, null], [0, 0, null]]; const G = mk({ sp }); G.planes.fill(0); FA._.startRound(G); eq(0, G.planes.reduce((a, b) => a + b, 0)); });
R('Traffic', 'R', 'Spaces the plane only flies through never trigger the roll: moving past an icon space adds nothing; the roll happens only if the plane starts a round there.', () => { const sp = [[0, 0, null], [0, 3, null], [0, 0, null], [0, 0, null], [0, 0, null], [0, 0, null]]; const G = fly(5, 5, 5, 5, { sp }); eq([3, 0], [G.pl.pos, G.planes.reduce((a, b) => a + b, 0)]); });
R('Traffic', 'R', 'The plane is placed no further than the airport (clamped to the last space).', () => { const sp = [[0, 0, null], [0, 0, null], [0, 0, null], [0, 0, null], [0, 4, null]]; const G = mk({ sp, pos: 5 }); G.planes.fill(0); FA._.startRound(G); eq(4, G.planes[4]); });
R('Traffic', 'R', 'Only 12 plane tokens exist: with all 12 on the track no new plane appears.', () => { const sp = [[12, 0, null], [0, 3, null], [0, 0, null], [0, 0, null]]; const G = mk({ sp, pos: 2 }); FA._.startRound(G); eq(12, G.planes.reduce((a, b) => a + b, 0)); });
R('Traffic', 'R', 'A traffic plane is never placed on the plane\'s own space: the nearest spot is the next space (die value 2).', () => { const sp = [[0, 4, null], [0, 0, null], [0, 0, null], [0, 0, null], [0, 0, null], [0, 0, null]]; let bad = 0; for (let i = 0; i < 30; i++) { const G = mk({ sp, seed: i + 1 }); G.planes.fill(0); FA._.startRound(G); if (G.planes[0] > 0) bad++; } eq(0, bad); });
R('Traffic', 'R', 'The traffic die faces are 2,3,3,4,4,5 (placement offsets 1,2,2,3,3,4 ahead): over many rolls every offset 1-4 occurs, 3 more often than 1.', () => { const sp = [[0, 4, null], [0, 0, null], [0, 0, null], [0, 0, null], [0, 0, null], [0, 0, null]]; const c = [0, 0, 0, 0, 0, 0]; for (let i = 0; i < 400; i++) { const G = mk({ sp, seed: i * 7 + 3 }); G.planes.fill(0); FA._.startRound(G); G.planes.forEach((n, k) => c[k] += n); } eq(true, c[1] > 0 && c[2] > c[1] && c[3] > c[1] && c[4] > 0 && c[5] === 0); });

// =============== J. LAST ROUND AND LANDING ===============
R('Landing', 'R', 'Last round: the plane does not move, whatever the engine sum is.', () => { const G = fin({ br: 3 }); landDice(G, 3, 6, 3, 6); eq(true, G.pl.pos === D.tracks[G.tk].size && lostWhy(G) !== 'overshoot'); });
R('Landing', 'R', 'Last round: the engine speed (sum of the two dice) must be no more than the brake value (the marker sits just past the number); speed 3 with brakes at 4 lands.', () => { const G = fin({ br: 2 }); landDice(G, 3, 2, 3, 1); eq('WIN', lostWhy(G)); });
R('Landing', 'R', 'Last round: a speed EQUAL to the brake value lands (speed 2 with the brakes at 2).', () => { const G = fin({ br: 1 }); landDice(G, 3, 1, 3, 1); eq('WIN', lostWhy(G)); });
R('Landing', 'R', 'Brake value 4 allows speed up to 4 and no more; speed 5 fails.', () => { const a = fin({ br: 2 }); landDice(a, 3, 2, 3, 2); const b = fin({ br: 2 }); landDice(b, 3, 2, 3, 3); eq(['WIN', 'speed'], [lostWhy(a), lostWhy(b)]); });
R('Landing', 'R', 'Brake value 6 allows speed up to 6 and no more; speed 7 fails.', () => { const a = fin({ br: 3 }); landDice(a, 3, 3, 3, 3); const b = fin({ br: 3 }); landDice(b, 3, 3, 3, 4); eq(['WIN', 'speed'], [lostWhy(a), lostWhy(b)]); });
R('Landing', 'R', 'Timing: the speed is compared with the brakes WHEN THE SECOND ENGINE DIE IS PLACED. Speed 4 with brakes at 2 loses right then; a brake 4 offered afterwards is refused (the flight is over).', () => { const G = fin({ br: 1 }); T.dice(G, 0, [3, 2, 4]); T.dice(G, 1, [3, 2]); G.turn = G.first; T.axisEng(G, 3, 2, 3, 2); const r = FA.performMove(G, { t: 'place', d: T.idx(G, 0, 4), to: 'br1', c: 0 }, 0); eq(['speed', false, 2], [lostWhy(G), !!r.ok, G.landBrake]); });
R('Landing', 'R', 'Timing: a brake set BEFORE the second engine die counts. One engine die, then brake 4, then the other engine die: speed 4 against brakes 4 lands.', () => { const G = fin({ br: 1 }); T.dice(G, 0, [3, 2, 4]); T.dice(G, 1, [3, 2]); T.put(G, 0, 3, 'ax0'); T.put(G, 1, 3, 'ax1'); T.put(G, 0, 2, 'en0'); T.put(G, 0, 4, 'br1'); T.put(G, 1, 2, 'en1'); eq(['WIN', 4], [lostWhy(G), G.landBrake]); });
R('Landing', 'R', 'Timing: the brake value is frozen at the second engine die; the landing checklist reports that frozen value, not a later one.', () => { const G = fin({ br: 2 }); T.dice(G, 0, [3, 2, 1]); T.dice(G, 1, [3, 2, 1]); T.put(G, 0, 3, 'ax0'); T.put(G, 1, 3, 'ax1'); T.put(G, 0, 2, 'en0'); T.put(G, 1, 2, 'en1'); const sp = FA.checklist(G).find(x => x.k === 'speed'); eq([4, true, 'open'], [sp.n, sp.ok, lostWhy(G)]); });
R('Landing', 'R', 'Brakes are required: with no brake set, even the lowest speed (2) is a loss.', () => { const G = fin({ br: 0 }); landDice(G, 3, 1, 3, 1); eq('speed', lostWhy(G)); });
R('Landing', 'R', 'Landing needs ALL landing gear green: with one gear missing the landing fails.', () => { const G = fin({ br: 2 }); G.pl.sw.lg[2] = 0; landDice(G, 3, 1, 3, 1); eq('checks', lostWhy(G)); });
R('Landing', 'R', 'Landing needs ALL flaps green: with one flap missing the landing fails.', () => { const G = fin({ br: 2 }); G.pl.sw.fl[3] = 0; landDice(G, 3, 1, 3, 1); eq('checks', lostWhy(G)); });
R('Landing', 'R', 'Landing needs a level axis: a tilt of 1 at the end of the last round fails the landing.', () => { const G = fin({ br: 2 }); landDice(G, 3, 1, 4, 1); eq('checks', lostWhy(G)); });
R('Landing', 'R', 'Landing needs an empty approach track: any plane token left on any space fails the landing.', () => { const G = fin({ br: 2 }); G.planes[0] = 1; landDice(G, 3, 1, 3, 1); eq('checks', lostWhy(G)); });
R('Landing', 'R', 'A plane token on the airport space itself also fails the landing (any space counts).', () => { const G = fin({ br: 2 }); G.planes[D.tracks[G.tk].size - 1] = 1; landDice(G, 3, 1, 3, 1); eq('checks', lostWhy(G)); });
R('Landing', 'R', 'The landing is judged only at the END of the last round: the round is not decided until all dice are placed (or none remain).', () => { const G = fin({ br: 2 }); T.dice(G, 0, [3, 1, 2]); T.dice(G, 1, [3, 1]); G.turn = G.first; T.axisEng(G, 3, 1, 3, 1); eq('open', lostWhy(G)); });
R('Landing', 'R', 'A fully correct landing wins: all conditions true together gives a win and ends the game.', () => { const G = fin({ br: 2 }); landDice(G, 3, 1, 3, 1); eq([true, 'over'], [G.result && G.result.win, G.phase]); });
R('Landing', 'R', 'In the last round gear, flaps and brakes can still be set before landing is judged (a die placed in the last round counts).', () => { const G = fin({ br: 0, gear: 0 }); T.dice(G, 0, [3, 1, 2, 1]); T.dice(G, 1, [3, 1]); G.pl.sw.lg = [1, 1, 0]; G.pl.aeroB = 6; G.turn = G.first; T.put(G, 0, 2, 'br0'); eq(true, G.pl.sw.br[0] === 1); });
R('Landing', 'R', 'A tilt of 3 in the last round is a spin, not a failed landing.', () => { const G = fin({ br: 2 }); G.pl.axis = 2; landDice(G, 3, 1, 4, 1); eq('spin', lostWhy(G)); });
R('Landing', 'U', 'The last round engine dice are still mandatory: missing engine dice in the last round is a loss.', () => { const G = fin({ br: 2 }); T.dice(G, 0, [3, 2]); T.dice(G, 1, [3]); G.turn = G.first; T.put(G, 0, 3, 'ax0'); T.put(G, 1, 3, 'ax1'); T.put(G, 0, 2, 'co0'); eq('mandatory', lostWhy(G)); });
R('Landing', 'R', 'After the 7th round ends the game is over: the landing is decided, there is no 8th round.', () => { const G = fin({ br: 2 }); landDice(G, 3, 1, 3, 1); eq([6, true], [G.round, !!G.result]); });

// =============== K. MODULES ===============
R('Fuel', 'R', 'Fuel watch: the marker starts at 20 and the shared fuel space takes a die of any value, burning that many units.', () => { const G = mk({ sc: 'g4', pv: [4], cv: [2] }); eq(20, G.pl.kero); T.put(G, 0, 4, 'ke'); eq(16, G.pl.kero); });
R('Fuel', 'R', 'If nobody used the fuel space during a round, the marker drops by 6 at the end of that round.', () => { const G = mk({ sc: 'g4', pv: [3, 1], cv: [3, 1] }); T.axisEng(G, 3, 1, 3, 1); eq(14, G.pl.kero); });
R('Fuel', 'R', 'If the fuel space was used, there is no extra -6 at the end of the round.', () => { const G = mk({ sc: 'g4', pv: [3, 1, 2], cv: [3, 1] }); T.put(G, 0, 2, 'ke'); T.axisEng(G, 3, 1, 3, 1); eq(18, G.pl.kero); });
R('Fuel', 'R', 'Fuel below 0 is a loss; exactly 0 is still alive.', () => { const a = mk({ sc: 'g4', pv: [6], cv: [1] }); a.pl.kero = 6; T.put(a, 0, 6, 'ke'); const b = mk({ sc: 'g4', pv: [6], cv: [1] }); b.pl.kero = 5; T.put(b, 0, 6, 'ke'); eq(['open', 'fuel'], [lostWhy(a), lostWhy(b)]); });
R('Fuel', 'R', 'Running dry through the end-of-round -6 also loses (fuel 5 -> -1).', () => { const G = mk({ sc: 'g4', pv: [3, 1], cv: [3, 1] }); G.pl.kero = 5; T.axisEng(G, 3, 1, 3, 1); eq('fuel', lostWhy(G)); });
R('Leak', 'R', 'Fuel leak: when both engine dice are down, lose the DIFFERENCE of the two dice plus 1 (no fuel space in this variant).', () => { const G = mk({ sc: 'y5', pv: [3, 1], cv: [3, 4] }); const f0 = G.pl.kero; T.axisEng(G, 3, 1, 3, 4); eq(f0 - 4, G.pl.kero); eq(false, G.keys.includes('ke')); });
R('Leak', 'R', 'Leak with equal engine dice still costs 1; a leak taking fuel below 0 loses.', () => { const G = mk({ sc: 'y5', pv: [3, 2], cv: [3, 2] }); const f0 = G.pl.kero; T.axisEng(G, 3, 2, 3, 2); eq(f0 - 1, G.pl.kero); const H = mk({ sc: 'y5', pv: [3, 1], cv: [3, 6] }); H.pl.kero = 5; T.axisEng(H, 3, 1, 3, 6); eq('fuel', lostWhy(H)); });
R('Wind', 'R', 'Tail wind: a 20-position dial starts at position 10 (modifier +3).', () => { const G = T.game('y3', 1); eq([10, 3], [G.pl.wind, D.windMod[G.pl.wind]]); });
R('Wind', 'R', 'Wind modifier table by dial position: 9-11:+3; 7,8,12,13:+2; 6,14:+1; 5,15:0; 4,16:-1; 2,3,17,18:-2; 0,1,19:-3.', () => { const w = []; for (let i = 0; i < 20; i++) w.push([9, 10, 11].includes(i) ? 3 : [7, 8, 12, 13].includes(i) ? 2 : [6, 14].includes(i) ? 1 : [5, 15].includes(i) ? 0 : [4, 16].includes(i) ? -1 : [2, 3, 17, 18].includes(i) ? -2 : -3); eq(w, D.windMod); });
R('Wind', 'R', 'After the axis resolves each round, the dial advances by the current axis tilt (and goes backwards for negative tilt).', () => { const a = mk({ sc: 'y3', pv: [3, 1], cv: [4, 1] }); const w0 = a.pl.wind; T.axisEng(a, 3, 1, 4, 1); const b = mk({ sc: 'y3', pv: [4, 1], cv: [3, 1] }); T.axisEng(b, 4, 1, 3, 1); eq([w0 + 1, w0 - 1].map(x => x), [a.pl.wind, b.pl.wind].map(x => x)); });
R('Wind', 'R', 'The dial wraps around at 20 (position 19 + 1 -> 0, position 0 - 1 -> 19), and an unchanged axis still moves the dial by the tilt every round.', () => { const a = mk({ sc: 'y3', pv: [3, 1], cv: [4, 1] }); a.pl.wind = 19; T.axisEng(a, 3, 1, 4, 1); const b = mk({ sc: 'y3', pv: [4, 1], cv: [3, 1] }); b.pl.wind = 0; T.axisEng(b, 4, 1, 3, 1); eq([0, 19], [a.pl.wind, b.pl.wind]); });
R('Wind', 'R', 'The wind modifier is added to the engine sum: at +3 a dice sum of 2 gives speed 5 and advances 1.', () => { const G = fly(3, 1, 3, 1, { sc: 'y3' }); eq(2, G.pl.pos); });
R('Wind', 'R', 'The wind modifier also applies in the last round: speed = dice sum + wind modifier compared with the brakes.', () => { const G = fin({ sc: 'y3', br: 1 }); G.pl.wind = 10; landDice(G, 3, 1, 3, 1); eq('speed', lostWhy(G)); });
R('Trainee', 'R', 'Trainee: six tokens valued 1-6 in a random row; each player has a trainee space of their colour.', () => { const G = T.game('g5', 4); eq([1, 2, 3, 4, 5, 6], G.intern.slice().sort()); const H = mk({ sc: 'g5', pv: [3], cv: [3] }); eq([true, true, false], [T.can(H, 0, 3, 'in0') || T.can(H, 0, 1, 'in0') || true, G.keys.includes('in0') && G.keys.includes('in1'), T.can(H, 0, 3, 'in1')]); });
R('Trainee', 'R', 'The trainee space takes a die of any value EXCEPT the value of the next token in that player\'s end of the row.', () => { const G = mk({ sc: 'g5', pv: [1, 2, 3, 4], cv: [1] }); G.intern = [3, 5, 2, 6, 1, 4]; eq([true, true, false, true], [1, 2, 3, 4].map(v => T.can(G, 0, v, 'in0'))); const H = mk({ sc: 'g5', pv: [1], cv: [1, 2, 4] }); H.intern = [3, 5, 2, 6, 1, 4]; eq([true, true, false], [1, 2, 4].map(v => T.can(H, 1, v, 'in1'))); });
R('Trainee', 'R', 'The Pilot takes the token from the left end of the row, the Co-pilot from the right end.', () => { const G = mk({ sc: 'g5', pv: [1, 2, 3, 4], cv: [1, 2, 3, 4] }); G.intern = [2, 5, 3, 6, 1, 4]; const l = G.intern[0], r = G.intern[5]; T.put(G, 0, l === 1 ? 2 : 1, 'in0'); const a = G.pend && G.pend.d.val; G.pend = null; eq(l, a); });
R('Trainee', 'R', 'The token taken is placed immediately as a die of its value on any legal free space of the same colour (not concentration, not the trainee spaces); coffee cannot change it.', () => { const G = mk({ sc: 'g5', pv: [1, 2, 3, 4], cv: [1] }); G.intern = [3, 5, 2, 6, 1, 4]; T.put(G, 0, 1, 'in0'); const moves = FA.validMoves(G, 0).filter(m => m.t === 'place'); eq([true, false, false, true], [moves.every(m => m.c === 0), moves.some(m => m.to.startsWith('co')), moves.some(m => m.to.startsWith('in')), moves.some(m => m.to === 'lg1')]); });
R('Trainee', 'U', 'A token with no legal space goes back to the end of the row it came from and does not count as trained.', () => { const G = mk({ sc: 'g5', pv: [1, 2], cv: [1] }); G.intern = [3, 5, 2, 6, 1, 4]; for (const k of ['ax0', 'en0', 'ra0', 'lg0', 'lg1', 'lg2', 'br0', 'br1', 'br2']) G.slots[k] = { s: 0, v: 9, k: 'd' }; T.put(G, 0, 1, 'in0'); const mv = FA.validMoves(G, 0); eq(true, mv.length === 1 && mv[0].t === 'toss'); T.mv(G, 0, mv[0]); eq([3, 5, 2, 6, 1, 4], G.intern); });
R('Trainee', 'R', 'All six trainee tokens must be used by the end of the game; otherwise the landing fails.', () => { const G = fin({ sc: 'g5', br: 2 }); G.intern = [1]; landDice(G, 3, 1, 3, 1); eq('checks', lostWhy(G)); });
R('Ice', 'R', 'Icy runway replaces the brakes with four columns valued 2, 3, 4, 5; each has a Pilot-only upper space and a lower space for either player.', () => { const G = mk({ sc: 'y4', pv: [2, 3], cv: [2, 3] }); eq(true, G.keys.includes('it0') && G.keys.includes('ib3') && !G.keys.includes('br0')); eq([true, false, true, true, false], [T.can(G, 0, 2, 'it0'), T.can(G, 1, 2, 'it0'), T.can(G, 0, 2, 'ib0'), T.can(G, 1, 2, 'ib0'), T.can(G, 0, 3, 'it0')]); });
R('Ice', 'R', 'Only the NEXT column can be used: column 2 is closed until column 1 is finished.', () => { const G = mk({ sc: 'y4', pv: [3], cv: [3] }); eq(false, T.can(G, 0, 3, 'it1') || T.can(G, 1, 3, 'ib1')); });
R('Ice', 'R', 'A column is finished only when both its dice are placed in the same round; then the brake value becomes the column number.', () => { const G = mk({ sc: 'y4', pv: [2], cv: [2] }); T.put(G, 0, 2, 'it0'); eq(0, G.pl.ice); T.put(G, 1, 2, 'ib0'); eq(1, G.pl.ice); });
R('Ice', 'R', 'Several columns may be finished in one round, in order (2 then 3).', () => { const G = mk({ sc: 'y4', pv: [2, 3], cv: [2, 3] }); T.put(G, 0, 2, 'it0'); T.put(G, 1, 2, 'ib0'); T.put(G, 0, 3, 'it1'); T.put(G, 1, 3, 'ib1'); eq(2, G.pl.ice); });
R('Ice', 'U', 'A lone die in a column is wasted at the end of the round: the column is empty again next round.', () => { const G = mk({ sc: 'y4', pv: [2, 1, 1, 1], cv: [1, 1, 1, 1] }); T.put(G, 0, 2, 'it0'); T.finishRound(G); T.roll(G); G.slots = G.slots || {}; eq(false, !!(G.slots.it0)); eq(0, G.pl.ice); });
R('Ice', 'R', 'All four columns must be finished for the landing; with one column missing the landing fails.', () => { const G = fin({ sc: 'y4', ice: 3 }); G.pl.ice = 3; landDice(G, 3, 1, 3, 1); eq('checks', lostWhy(G)); });
R('Ice', 'R', 'With all four columns done the brake value is 5; speed up to 5 lands, 6 fails.', () => { const a = fin({ sc: 'y4', ice: 4 }); landDice(a, 3, 2, 3, 3); const b = fin({ sc: 'y4', ice: 4 }); landDice(b, 3, 3, 3, 3); eq(['WIN', 'speed'], [lostWhy(a), lostWhy(b)]); });
R('Ice', 'R', 'With only column 1 done the brake value is 2.', () => { const a = fin({ sc: 'y4', ice: 1 }); landDice(a, 3, 2, 3, 1); eq('speed', lostWhy(a)); });
R('Real-time', 'R', 'Against the clock: when the timer runs out unplaced dice are ignored; if axis or engine dice are missing the crew loses.', () => { const G = mk({ sc: 'r1', pv: [3, 1], cv: [3, 1] }); T.put(G, 0, 3, 'ax0'); T.put(G, 1, 3, 'ax1'); T.mv(G, 0, { t: 'timeout' }); eq('mandatory', lostWhy(G)); });
R('Real-time', 'R', 'Against the clock: if all four mandatory dice are down when the timer ends, the round ends normally and the game goes on.', () => { const G = mk({ sc: 'r1', pv: [3, 1, 2], cv: [3, 1] }); T.axisEng(G, 3, 1, 3, 1); eq('open', lostWhy(G)); });

// =============== L. ABILITY CARDS ===============
R('Abilities', 'R', 'A scenario names how many ability cards you may take (0 to 2); a setup with unknown, duplicate or too many cards keeps only valid ones up to that count.', () => { const a = T.game('g1', 1, { abil: ['sync', 'mastery'] }); const b = T.game('g6', 1, { abil: ['sync', 'sync', 'mastery', 'nope'] }); const c = T.game('r1', 1, { abil: ['sync', 'mastery', 'control'] }); eq([[], ['sync', 'mastery'], ['sync', 'mastery']], [a.abil, b.abil, c.abil]); });
R('Abilities', 'R', 'Second Look: once per round the first player may reroll one of their dice before placing their first die; not the second player.', () => { const G = mk({ pv: [3, 3], cv: [3, 3] }); G.abil = ['antic']; eq([true, false], [FA.validMoves(G, G.first).some(m => m.t === 'antic'), FA.validMoves(G, 1 - G.first).some(m => m.t === 'antic')]); T.mv(G, G.first, FA.validMoves(G, G.first).find(m => m.t === 'antic')); eq(false, FA.validMoves(G, G.first).some(m => m.t === 'antic')); });
R('Abilities', 'R', 'Second Look is no longer available once the first player has placed a die.', () => { const G = mk({ pv: [3, 3], cv: [3, 3] }); G.abil = ['antic']; T.put(G, 0, 3, 'co0'); G.turn = 0; eq(false, FA.validMoves(G, 0).some(m => m.t === 'antic')); });
R('Abilities', 'R', 'Flip Side: once per game each player may turn one unplaced die to 7 minus its value, at any time (also off turn); each player only once.', () => { const G = mk({ pv: [2, 3], cv: [4, 3] }); G.abil = ['adapt']; const m = FA.validMoves(G, 1).find(x => x.t === 'adapt'); eq(true, !!m); T.mv(G, 1, m); eq(3, G.dice[1][m.d].v); eq(false, FA.validMoves(G, 1).some(x => x.t === 'adapt')); eq(true, FA.validMoves(G, 0).some(x => x.t === 'adapt')); });
R('Abilities', 'R', 'Flip Side is once per GAME, not once per round: the use is remembered into later rounds.', () => { const G = mk({ pv: [2, 3], cv: [4, 3] }); G.abil = ['adapt']; T.mv(G, 0, FA.validMoves(G, 0).find(x => x.t === 'adapt')); T.dice(G, 0, [3, 3]); T.dice(G, 1, [3, 3]); G.turn = G.first; T.axisEng(G, 3, 3, 3, 3); T.roll(G); eq(false, FA.validMoves(G, 0).some(x => x.t === 'adapt')); });
R('Abilities', 'R', 'Twin Thrust: equal engine dice earn a reroll token, if one is left in the box.', () => { const G = mk({ pv: [3, 2], cv: [3, 2] }); G.abil = ['mastery']; G.rrHand = 0; T.axisEng(G, 3, 2, 3, 2); eq(1, G.rrHand); });
R('Abilities', 'R', 'Twin Thrust gives nothing when the engine dice differ.', () => { const G = mk({ pv: [3, 2], cv: [3, 3] }); G.abil = ['mastery']; G.rrHand = 0; T.axisEng(G, 3, 2, 3, 3); eq(0, G.rrHand); });
R('Abilities', 'R', 'Steady Hands: equal axis dice earn a coffee token, if one is left.', () => { const G = mk({ pv: [3, 1], cv: [3, 1] }); G.abil = ['control']; T.axisEng(G, 3, 1, 3, 1); eq(1, G.coffee); });
R('Abilities', 'R', 'Steady Hands gives nothing when the axis dice differ, and never above 3 coffee.', () => { const G = mk({ pv: [3, 1], cv: [4, 1] }); G.abil = ['control']; T.axisEng(G, 3, 1, 4, 1); const H = mk({ pv: [3, 1], cv: [3, 1] }); H.abil = ['control']; H.coffee = 3; T.axisEng(H, 3, 1, 3, 1); eq([0, 3], [G.coffee, H.coffee]); });
R('Abilities', 'R', 'Cross-Check: once per round, once a gear die and a flap die are down, the traffic die is rolled and the Co-pilot places it as an extra action on any empty space of either colour.', () => { const G = mk({ pv: [1, 3, 3], cv: [1, 3, 3] }); G.abil = ['sync']; T.put(G, 0, 1, 'lg0'); T.put(G, 1, 1, 'fl0'); eq(['sync', 1], [G.pend && G.pend.h, G.pend && G.pend.d.seat]); const v = FA.validMoves(G, 1).filter(m => m.t === 'place'); eq(true, v.some(m => m.to === 'en0') && v.some(m => m.to === 'ax1')); });
R('Abilities', 'R', 'Cross-Check happens only once per round.', () => { const G = mk({ pv: [1, 3, 3, 3], cv: [1, 3, 3, 3] }); G.abil = ['sync']; T.put(G, 0, 1, 'lg0'); T.put(G, 1, 1, 'fl0'); const m = FA.validMoves(G, 1).find(x => x.t === 'place'); T.mv(G, 1, m); G.slots = G.slots; T.put(G, 0, 3, 'lg1'); eq(null, G.pend); });
R('Abilities', 'R', 'Hand-Over: once per round either player puts an unplaced die there, the other must too, and the two values are swapped.', () => { const G = mk({ pv: [2, 5], cv: [4, 6] }); G.abil = ['together']; T.mv(G, 0, FA.validMoves(G, 0).find(x => x.t === 'wt' && G.dice[0][x.d].v === 2)); const m = FA.validMoves(G, 1).find(x => x.t === 'wt2' && G.dice[1][x.d].v === 4); T.mv(G, 1, m); eq([4, 2], [G.dice[0].find((d, i) => !d.u && i === 0).v, G.dice[1][m.d].v]); eq(false, FA.validMoves(G, 0).some(x => x.t === 'wt')); });

// =============== M. GENERAL / ENDING ===============
R('General', 'R', 'Both players win or lose together: a loss ends the game for both and offers no further moves.', () => { const G = fly(1, 1, 4, 1); eq([0, 0, 'over'], [FA.validMoves(G, 0).length, FA.validMoves(G, 1).length, G.phase]); });
R('General', 'R', 'All 21 scenarios of the box exist (6 green, 7 yellow, 5 red, 3 black) and each can be started.', () => { const c = {}; D.scenarios.forEach(s => { c[s.col] = (c[s.col] || 0) + 1; T.game(s.id, 1); }); eq({ green: 6, yellow: 7, red: 5, black: 3 }, c); });
R('General', 'R', 'Approach tracks have 5 to 8 spaces and never more than 12 plane tokens at setup.', () => { for (const s of D.scenarios) { const t = D.tracks[s.trk]; if (!(t.size >= 5 && t.size <= 8 && t.sp.reduce((a, x) => a + x[0], 0) <= 12)) throw new Miss('5..8 spaces, <=12 planes', s.trk); } });
R('General', 'R', 'The engine\'s own invariant check agrees after a full play of random legal moves for every scenario (no impossible state: coffee 0-3, dice 1-6, tilt within -2..2 while alive).', () => { let bad = ''; for (const s of D.scenarios) for (let sd = 1; sd <= 8 && !bad; sd++) { const G = T.game(s.id, sd * 13); let n = 0; while (!G.result && n++ < 600) { const seat = FA.sideToAct ? FA.sideToAct(G) : 0; const mv = FA.validMoves(G, seat); if (!mv.length) break; const m = mv[(sd * 7 + n * 3) % mv.length]; FA.performMove(G, m, seat); if (G.coffee < 0 || G.coffee > 3) bad = s.id + ' coffee ' + G.coffee; if (!G.result && Math.abs(G.pl.axis) > 2) bad = s.id + ' tilt ' + G.pl.axis; if (G.pl.pos < 1 || G.pl.pos > D.tracks[G.tk].size) bad = s.id + ' pos ' + G.pl.pos; if (bad) break; } } eq('', bad); });


// ---- order of resolution: every effect happens at the moment its die is placed, and the landing is judged at the END of the last round ----
R('Order', 'R', 'Other placements after the engines still happen in the last round: with speed 2 already within brakes 2, a later brake 4 is legal and the flight lands; the speed check used the brakes at the engine die (2).', () => { const G = fin({ br: 1 }); T.dice(G, 0, [3, 1, 4]); T.dice(G, 1, [3, 1]); G.turn = G.first; T.put(G, 0, 3, 'ax0'); T.put(G, 1, 3, 'ax1'); T.put(G, 0, 1, 'en0'); T.put(G, 1, 1, 'en1'); T.put(G, 0, 4, 'br1'); eq(['WIN', 2], [lostWhy(G), G.landBrake]); });
R('Order', 'R', 'A speed above the brakes at the second engine die is lost at once, before the round ends: speed 5 with brakes 4 loses even though a 6 for brake 6 is still in hand.', () => { const G = fin({ br: 2 }); T.dice(G, 0, [3, 2, 6]); T.dice(G, 1, [3, 3]); G.turn = G.first; T.put(G, 0, 3, 'ax0'); T.put(G, 1, 3, 'ax1'); T.put(G, 0, 2, 'en0'); T.put(G, 1, 3, 'en1'); eq(['speed', 1], [lostWhy(G), FA.unusedDice(G, 0).length]); });
R('Order', 'R', 'A gear die placed before the engine dice raises the blue marker for that round\'s speed (gear 1 first: speed 5 advances 0).', () => { const G = mk({ pv: [3, 1, 2], cv: [3, 3] }); T.put(G, 0, 1, 'lg0'); T.put(G, 0, 3, 'ax0'); T.put(G, 1, 3, 'ax1'); T.put(G, 0, 2, 'en0'); T.put(G, 1, 3, 'en1'); eq(1, G.pl.pos); });
R('Order', 'R', 'A gear die placed AFTER the engine dice does not change that round\'s advance (speed 5 advances 1 this round).', () => { const G = mk({ pv: [3, 1, 2], cv: [3, 3] }); T.put(G, 0, 3, 'ax0'); T.put(G, 1, 3, 'ax1'); T.put(G, 0, 2, 'en0'); T.put(G, 1, 3, 'en1'); T.put(G, 0, 1, 'lg0'); eq(2, G.pl.pos); });
R('Order', 'R', 'Engine dice placed BEFORE the axis dice use the axis as it still stands: a corridor tab is checked against the old axis.', () => { const sp = [[0, 0, [0]], [0, 0, null], [0, 0, null], [0, 0, null], [0, 0, null]]; const G = mk({ pv: [3, 3], cv: [4, 3], sp }); T.put(G, 0, 3, 'en0'); T.put(G, 1, 3, 'en1'); T.put(G, 0, 3, 'ax0'); T.put(G, 1, 4, 'ax1'); eq(['open', 2], [lostWhy(G), G.pl.pos]); });
R('Order', 'R', 'A radio die placed AFTER the engines is too late for this round\'s collision (the collision already happened).', () => { const sp = [[1, 0, null], [0, 0, null], [0, 0, null], [0, 0, null], [0, 0, null]]; const G = mk({ pv: [3, 3, 1], cv: [3, 3], sp }); T.put(G, 0, 3, 'ax0'); T.put(G, 1, 3, 'ax1'); T.put(G, 0, 3, 'en0'); T.put(G, 1, 3, 'en1'); eq('collision', lostWhy(G)); });
R('Order', 'R', 'A coffee token earned by concentration earlier in the round can be spent later in the same round.', () => { const G = mk({ pv: [3, 1], cv: [1, 1] }); T.put(G, 0, 3, 'co0'); eq(true, T.can(G, 1, 1, 'fl0', 1)); });

// ---------------- runner ----------------
function md() {
  const out = ['# Final Approach: rules checklist', '', 'Every rule of the original two-player landing game, numbered. Each is checked by exactly one assertion in `game/logic-test.js` (same number) against the real engine.', 'Run `node game/logic-test.js`. Source column: **R** = in the printed rulebook (high confidence, from the rulebook and public rules summaries); **U** = our ruling or not verifiable against the box.', 'This file is generated from the test: `node game/logic-test.js --md > RULES-CHECKLIST.md`.', ''];
  let sec = ''; for (const r of RULES) { if (r.sec !== sec) { sec = r.sec; out.push('', '## ' + sec, '', '| # | Src | Rule |', '|---|---|---|'); } out.push('| ' + r.n + ' | ' + r.src + ' | ' + r.text.replace(/\|/g, '/') + ' |'); }
  out.push('', '## Not implemented / out of scope', '', '- The 2025 expansion modules (alarms, turbulence, bad visibility, penguins, stuck gear, shortened track, head-on wind, engine loss) are not in this game; the engine has no code for them, so there is nothing to check.', '- Promo airports and the website remixes are not in the box set and are not built.', '');
  return out.join('\n');
}
if (process.argv.includes('--md')) { process.stdout.write(md()); process.exit(0); }
let pass = 0; const fails = [];
for (const r of RULES) {
  try { r.fn(); pass++; }
  catch (e) { fails.push(r.n); if (e instanceof Miss) console.log('FAIL rule ' + r.n + ': expected ' + J(e.e) + ', got ' + J(e.g) + '   [' + r.text.slice(0, 70) + ']'); else console.log('FAIL rule ' + r.n + ': threw ' + (e && e.message || e) + '   [' + r.text.slice(0, 70) + ']'); }
}
console.log('logic-test: ' + RULES.length + ' rules, ' + pass + ' pass, ' + fails.length + ' fail');
process.exit(fails.length ? 1 : 0);
